#include <stdint.h>
#include<stdio.h>
#include<string.h>

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif

#define STM32F407xx
#include "stm32f4xx.h"
#include "spi.h"
#include "sd.h"

uint8_t tx_buffer[512];
uint8_t rx_buffer[512];



void USART2_SendChar(char c){
	while (!(USART2->SR & (1U <<7 )));
	USART2->DR = c;
}

void USART2_SendString(char *str){
	while (*str)
		USART2_SendChar(*str++);
}

// Retarget stdio printf to USART2
int _write(int file, char *ptr, int len)
{
    for (int i = 0; i < len; i++)
    {
        USART2_SendChar(ptr[i]);
    }
    return len;
}

int main(void)
{
	RCC->AHB1ENR |= (1U << 0); //enabling clock GPIOA
	RCC->APB1ENR |= (1U << 17);//enabling  clock for USART2

	//clearing bits
	GPIOA->MODER &= ~((3U << 4) | (3U << 6));

	//setting mode to alternate function for USART2(PA2,3)
	GPIOA->MODER |= ((2U << 4) | (2U << 6));

	//selecting  AF as USART2
	GPIOA->AFR[0] &= ~((0xFU << 8) | (0xFU << 12));
	GPIOA->AFR[0] |= ((7U << 8) | (7U << 12));

	//set baud rate
	USART2->BRR |= 0x8B;

	//enabling usart and transmitter
	USART2->CR1 &= ~((1U << 3) | (1U << 13));
	USART2->CR1 |= ((1U << 3) | (1U << 13));

	printf("System Boot OK! SystemCoreClocks: %lu Hz\r\n", 16000000UL);

	SPI1_Init();
	if (SD_Init() != 0){
		while(1);
	}

	for(int i = 0; i < 512 ; i++){
		tx_buffer[i] = (uint8_t)(i & 0xFF);
	}
	memset(rx_buffer, 0, 512);

	if (SD_Write_Single_Block(tx_buffer, 2048) != 0){
		while(1);
	}
	if (SD_Read_Single_Block(rx_buffer, 2048) != 0){
		while(1);
	}


	uint8_t errors = 0;

	for(int i = 0 ; i < 512 ; i++){
		if(tx_buffer[i] != rx_buffer[i]){
			errors++;
		}
	}
	if(errors > 0){
		printf("Mismatch between read and written data.\r\n");
	}
	else{
		printf("Data matched! successfully.\r\n");
	}
	while (1){

	}

}
